// Generated by bloom from an `extern native` interface: regenerated on every build, never edited.
import { type ComponentType, createElement } from 'react';
import { type Child, Embed } from '@oxy.so/bloom-language';

declare const require: (id: string) => unknown;

type Host = ComponentType<Record<string, unknown>>;

/** A native view takes the space it is offered (a `.frame()` sizes it). */
const FILL = { flexGrow: 1, alignSelf: 'stretch' } as const;

/** The native component `name`, or `null` where the build does not link it (the web, tests). */
function hostOf(name: string, load: () => unknown): Host | null {
  try {
    const { UIManager } = require('react-native') as {
      UIManager?: { hasViewManagerConfig?: (name: string) => boolean };
    };
    if (UIManager?.hasViewManagerConfig?.(name) !== true) return null;
    return (load() as { default: Host }).default;
  } catch {
    return null;
  }
}

let BloomIslandHost: Host | null | undefined;

/** The native view `BloomIsland` (a Fabric component). It draws nothing where the build does not link it. */
export function BloomIsland(island: string, props: string, themePreset: string | undefined, themeScheme: string | undefined, onIslandEvent: ((event: { readonly name: string; readonly payload: string }) => void) | undefined): Child {
  if (BloomIslandHost === undefined) BloomIslandHost = hostOf('BloomIsland', () => require('./BloomIslandNativeComponent'));
  if (BloomIslandHost === null) return Embed(null);
  return Embed(
    createElement(BloomIslandHost, {
      style: FILL,
    island,
    props,
    themePreset,
    themeScheme,
    onIslandEvent: onIslandEvent === undefined ? undefined : (e: { nativeEvent: { name: string; payload: string } }) => onIslandEvent(e.nativeEvent),
    }) as Parameters<typeof Embed>[0],
  );
}
